  "core.wormholeBattle.016": { zh: "🕳 弹药回收装置：这一场打出去的弹药回收了 {p1} 发（{p2}%）。", en: "🕳 Ammo recovery unit: {p1} rounds fired in this fight were recovered ({p2}%)." },
  "core.wormholeBattle.017": { zh: "🕳 战地维修单元：编队装甲与结构各回复 {p1}%（不耗货仓组件）。", en: "🕳 Field repair unit: the formation recovered {p1}% armour and hull each (no hold kits consumed)." },
  "core.wormholeBattle.018": { zh: "🕳 第 {p1} 层守卫已清：可以「继续深入」或「撤离」。", en: "🕳 The layer {p1} guard is down: you can Descend or Withdraw." },
  "core.wormholeBattle.019": { zh: "🕳 回合已耗尽：只能撤离。", en: "🕳 Turns are exhausted: withdrawal is the only option." },
  "core.wormholeBattle.020": { zh: "🕳 回合不足以继续推进：只能撤离（{p1}）。", en: "🕳 Not enough turns to push on: withdrawal is the only option ({p1})." },
  "core.wormholeBattle.021": { zh: "🕳 带回 {p1}：已直接接入核心库（不占货仓、不入仓库）。", en: "🕳 Brought back {p1}: it went straight into core storage (no hold space, no warehouse)." },
  "core.wormholeBattle.022": { zh: "🕳 撤离放弃：临时空间里的 {p1} 类物资留在洞里（未整理的按丢弃处理）。", en: "🕳 Left behind on withdrawal: {p1} kinds of goods in temporary space stay in the wormhole (unsorted goods are treated as discarded)." },
  "core.wormholeBattle.023": { zh: "🕳 撤离失败：编队已经没了（全灭或档案异常）——本趟按全损处理。", en: "🕳 Withdrawal failed: the formation is gone (wiped out or the record is corrupt) — this run counts as a total loss." },
  "core.wormholeBattle.024": { zh: "第 {p1} 层守卫", en: "the layer {p1} guardian" },
  "core.wormholeBattle.025": { zh: "撤离", en: "the withdrawal" },
