  "core.expedition.006": { zh: "返航空间站途中：到站后再安排远征。", en: "On the way back to a station: arrange the expedition after docking." },
  "core.expedition.007": { zh: "快递投送途中：暂不能出发远征——到站自动结算后再安排。", en: "A courier delivery is under way: an expedition has to wait until it settles on arrival." },
  "core.expedition.008": { zh: "精炼炉正由你亲自运转：先停炉才能出发远征（想自动精炼可改用 AI 核心驱动）。", en: "You are running a refinery by hand: stop it before setting out on an expedition (an AI core can refine automatically instead)." },
  "core.expedition.009": { zh: "制造作业正由你亲自开线：先取消它才能出发远征（想自动制造可改用 AI 核心驱动）。", en: "You are running a production line by hand: cancel it before setting out on an expedition (an AI core can manufacture automatically instead)." },
  "core.expedition.010": { zh: "该目标不是敌人窝点，无法作为赏金任务目标。", en: "That target is not a hostile lair, so it cannot be a bounty objective." },
