  "core.expedition.013": { zh: "主控在虫洞里（已锁定）：先暂停并召回整队，才能出击。", en: "The command ship is inside a wormhole (locked): pause and recall the whole team before sortieing." },
  "core.expedition.014": { zh: "目标已不存在，无法开战。", en: "The target no longer exists, so the fight cannot start." },
