  "core.expedition.026": { zh: "战果已入账：舰队返港中（本地悬赏返航段约 2 分钟，胜利返航不可召回）。", en: "Spoils booked: the fleet is heading back to port (the return leg of a local bounty takes about 2 minutes, and a victorious return cannot be recalled)." },
  "core.expedition.027": { zh: "舰队开始返航（去程时间并入返航）。", en: "The fleet is heading home (the outbound leg is folded into the return)." },
