  "ui.Expedition.010": { zh: "{p1}（{p2}）· {p3}，剩余约 {p4}——进度与「召回」在顶部活动栏", en: "{p1} ({p2}) · {p3}, about {p4} left — progress and Recall are in the top activity bar" },
  "ui.Expedition.011": { zh: "停靠副站「", en: "Docked at outpost “" },
