  "ui.Expedition.018": { zh: "✓ 通路无交叉 · 拖动星系圆点调整布局", en: "✓ No route crossings · drag the system dots to lay it out" },
  "ui.Expedition.019": { zh: "保存到本地（重启保留）并把坐标 JSON 复制到剪贴板（可发给开发者合入默认布局）", en: "Save locally (kept across restarts) and copy the coordinate JSON to the clipboard (send it to the developer to fold into the default layout)" },
