  "ui.Expedition.029": { zh: "交付循环进行中（顶部活动栏可查看进度/取消）", en: "Delivery loop in progress (check progress or cancel it in the top activity bar)" },
  "ui.Expedition.030": { zh: "仓库建材不足（需要：{matNames}）——备料后再出发", en: "Not enough materials in storage (needs: {matNames}) — gather them before setting out" },
  "ui.Expedition.031": { zh: "一键交付循环：每趟把货仓装满当前档材料单建材（当前空闲 {freeM3} m³）→ 真实航程到点自动清仓交付 → 自动返港续趟，直到副站建成或仓库建材耗尽（随时可取消停止）", en: "One-click delivery loop: each trip fills the hold with the materials on the current tier's list ({freeM3} m³ free right now) → flies the real distance and empties into the site on arrival → returns for another load, until the outpost is built or the warehouse runs out of materials (cancel at any time)" },
  "ui.Expedition.032": { zh: "仓库建材", en: "Materials in storage" },
  "ui.Expedition.033": { zh: "m³——装满出发，到点清仓交付，自动循环至建成或仓库耗尽", en: "m³ — leaves full, empties into the site on arrival, and loops until the build is done or the warehouse runs out" },
