  "ui.Expedition.063": { zh: "再点一次确认转战：采矿立即结束（已采的货随船），舰队从矿带星系出发", en: "Click again to confirm the switch: mining ends at once (the cargo already mined stays aboard) and the fleet sets out from the belt system" },
  "ui.Expedition.064": { zh: "全部材料由采矿 → 精炼产出；可「前往工地交付」自动运料，或到现场手动逐项提交。", en: "Every material comes from mining → refining; use Go deliver to the site to haul them automatically, or hand them over item by item on site." },
  "ui.Expedition.065": { zh: "不在工地现场：可一键「前往工地交付」——每趟把货仓装满当前档材料单建材，按真实航程驶往工地，到点自动清仓交付；仓库还有建材就自动续趟，直到副站建成或仓库建材耗尽（耗尽会弹窗提示）；途中可在顶部活动栏取消（= 停止循环）。", en: "Not at the build site: use Go deliver to the site in one click — each trip fills the hold with the current tier's materials and flies the real distance to the site, emptying into it on arrival; as long as the warehouse has materials it keeps shuttling until the outpost is built or the materials run out (a popup warns you when they do). The loop can be cancelled from the top activity bar at any time." },
  "ui.Expedition.066": { zh: "仓库建材不足（当前档需要 {p1}）——备料后再出发", en: "Not enough materials in storage (this tier needs {p1}) — gather them before setting out" },
  "ui.Expedition.067": { zh: "从「{p1}」出发：装满货仓（空闲 {p2} m³）→ 到点清仓自动交付 → 自动返港续趟至建成或仓库耗尽（可随时取消）", en: "Departing from “{p1}”: fills the hold ({p2} m³ free) → empties into the site on arrival → returns for another load until the build is done or the warehouse runs out (cancel any time)" },
  "ui.Expedition.068": { zh: "声望", en: "Reputation" },
  "ui.Expedition.069": { zh: "召回扫描艇：已扫部分按比例保留，下次对该星系扫描只需补扫剩余窗口（不牵动舰船，也不影响其它活动）", en: "Recall the scan ship: the progress made is kept proportionally, and the next scan of that system only covers what remains (it involves no ship and blocks no other activity)" },
  "ui.Expedition.070": { zh: "已召回扫描艇：已扫进度保留，下次对该星系扫描只补扫剩余窗口。", en: "Scan ship recalled: progress is kept, and the next scan of that system only covers what remains." },
