  "ui.FitPage.024": { zh: "装配台", en: "Fitting bay" },
  "ui.FitPage.025": { zh: "装备随船 · 进入其它船的装配台请在「舰船」页点卡片「⚒ 装配」", en: "Modules travel with the ship · to open another ship's fitting bay, click the ⚒ Fitting button on its card on the Ships page" },
  "ui.FitPage.026": { zh: "装配目标", en: "Fitting target" },
