  "ui.FitPage.028": { zh: "非驾驶船", en: "Not the piloted ship" },
  "ui.FitPage.029": { zh: "当前驾驶船 · 装备随船", en: "Piloted ship · modules travel with it" },
  "ui.FitPage.030": { zh: "来自「舰船」页卡片 · 此船不在驾驶（装配不影响驾驶状态）", en: "From the ship's card on the Ships page · this ship is not piloted (fitting does not change that)" },
  "ui.FitPage.031": { zh: "把当前这艘船的实装（三类槽位装备 + 无人机舱装载）存成一套方案；方案按船型归口，同型号任意一艘都能套用", en: "Save this ship's actual fit (modules in all three slot types plus drone bay load) as a preset; presets are filed by hull, so any ship of the same hull can apply it" },
  "ui.FitPage.032": { zh: "保存装配", en: "Save fitting" },
  "ui.FitPage.033": { zh: "装配方案", en: "Fitting presets" },
  "ui.FitPage.034": { zh: "间接属性", en: "Indirect stats" },
  "ui.FitPage.035": { zh: "无人机舱（含甲板扩展）", en: "Drone bay (incl. deck expansion)" },
  "ui.FitPage.036": { zh: "库存为空——装置开战即停机（不会自动修复）", en: "Storage empty — the module stops the moment combat starts (it will not repair itself)" },
  "ui.FitPage.037": { zh: "存量偏少——长局可能中途停机", en: "Low stock — a long run may run dry mid-fight" },
  "ui.FitPage.038": { zh: "存量充足", en: "Plenty in stock" },
  "ui.FitPage.039": { zh: "维修组件（运转消耗）", en: "Repair kits (consumed while running)" },
