  "ui.FitPage.049": { zh: "机动速度", en: "Maneuver speed" },
  "ui.FitPage.050": { zh: "跃迁速度（含装备）", en: "Warp speed (with modules)" },
  "ui.FitPage.051": { zh: "已占", en: "Used" },
  "ui.FitPage.052": { zh: "卸下", en: "Unfit" },
  "ui.FitPage.053": { zh: "装配方案 ·", en: "Fitting presets ·" },
  "ui.FitPage.054": { zh: "方案按船型保存：同一型号的任意一艘（含以后新建的）都能套用。套用 = 先把这艘船现有装备全部卸回装备库、无人机退回仓库，再按方案装；装备库缺件、CPU 超预算或机舱放不下时，能装的先装上，未装的逐条列出（所以方案凑不齐时结果可能不如套用前）。方案里不含弹药档位（弹种仍在右栏手动设）。", en: "Presets are saved per hull: any ship of that hull, including ones built later, can apply them. Applying strips the ship's current modules back to Module Storage and its drones back to storage, then fits the preset; if storage is short, the CPU budget is exceeded or the bay cannot hold everything, whatever fits goes on first and the rest is listed line by line (so an incomplete preset can leave the ship worse off than before). Presets carry no ammo tier — ammo is still set by hand in the right-hand column." },
  "ui.FitPage.055": { zh: "关闭", en: "Close" },
  "ui.FitPage.056": { zh: "还没有方案——点下面的「把当前装配存为新方案」，或先按当前装配点标题栏右侧的「保存装配」。", en: "No presets yet — click Save the current fitting as a new preset below, or start from the current fit and use Save fitting at the right of the title bar." },
  "ui.FitPage.057": { zh: "改好", en: "Done" },
  "ui.FitPage.058": { zh: "用当前装配覆盖这一套？", en: "Overwrite this preset with the current fitting?" },
  "ui.FitPage.059": { zh: "把当前这艘船的实装（三类槽位 ＋ 无人机舱装载）写进这一套方案；方案名与位置不变", en: "Write this ship's actual fit (all three slot types plus drone bay load) into this preset; its name and position stay as they are" },
  "ui.FitPage.060": { zh: "确认覆盖", en: "Confirm overwrite" },
  "ui.FitPage.061": { zh: "展开这套方案里逐位装了什么（高/中/低 逐位 ＋ 无人机舱装载）", en: "Expand what this preset fits slot by slot (high / mid / low, plus drone bay load)" },
