  "ui.FitPage.063": { zh: "明细", en: "Details" },
  "ui.FitPage.064": { zh: "套用", en: "Apply" },
  "ui.FitPage.065": { zh: "用当前这艘船的装配覆盖这一套方案（覆盖前会先确认；方案名与位置不变）", en: "Overwrite this preset with the current ship's fitting (a confirmation comes first; the preset's name and position stay as they are)" },
  "ui.FitPage.066": { zh: "替换", en: "Replace" },
  "ui.FitPage.067": { zh: "重命名", en: "Rename" },
  "ui.FitPage.068": { zh: "删除", en: "Delete" },
  "ui.FitPage.069": { zh: "（未知件）", en: "(unknown module)" },
  "ui.FitPage.070": { zh: "未装载", en: "Not loaded" },
  "ui.FitPage.071": { zh: "（未知机型）", en: "(unknown model)" },
  "ui.FitPage.072": { zh: "另有", en: "Also" },
  "ui.FitPage.073": { zh: "位超出本船槽位，套用时会被忽略。", en: "slots exceed this ship's slots and are ignored when applying." },
  "ui.FitPage.074": { zh: "把当前装配存为新方案", en: "Save the current fitting as a new preset" },
  "ui.FitPage.075": { zh: "把三类槽位上的装备全部卸回装备库（甲板扩容器一并卸下，超出机舱的无人机自动退回仓库）", en: "Unfit every module from all three slot types back to Module Storage (deck expanders come off too, and drones beyond the bay return to storage automatically)" },
  "ui.FitPage.076": { zh: "一键卸下全部装备", en: "Unfit every module" },
  "ui.FitPage.077": { zh: "套用会先卸光这艘船的装备与无人机，再按方案装；凑不齐的逐条列出。", en: "Applying first strips this ship's modules and drones, then fits the preset; anything missing is listed line by line." },
  "ui.FitPage.078": { zh: "（更换）", en: " (swap)" },
  "ui.FitPage.079": { zh: "（装入）", en: " (load)" },
  "ui.FitPage.080": { zh: "以下为该槽位可安装的全部装备（装备库库存）；点击即装入/更换（旧件自动卸回装备库）。卡片下方绿/红段为装后与当前对比：火力按名义值估算（全命中、不计距离衰减）；同类多装同样计入 CPU 校验。默认按稀有度从高到低排列。红色的「CPU 剩 …（差 N）」= 装后超预算，这件装不上（先卸件，或低槽装一件「协处理器」扩容）；红色的属性段只是数值下降，照样装得上。", en: "Everything that fits this slot (from Module Storage); click to fit or swap (the old module returns to storage automatically). The green and red numbers under each card compare after-fitting with now: firepower is a nominal estimate (every shot hits, no range falloff), and stacking several of a kind counts against the CPU budget too. Sorted by rarity, highest first. A red \"CPU left … (short N)\" means the fit goes over budget and cannot be installed (unfit something, or put a Coprocessor in a low slot); a red stat line only means the number drops — the module still fits." },
