  "ui.Handbook.020": { zh: "任何舰船进港（停靠母港或已建成副站）都会自动整仓卸入物品仓库（无限容量、不随船）。", en: "Every ship that docks (at the home port or a completed outpost) empties its hold into the warehouse automatically (unlimited capacity, and it stays ashore)." },
  "ui.Handbook.021": { zh: "手动与例外", en: "Manual operation and exceptions" },
