  "ui.Handbook.052": { zh: "五个档位", en: "Five tiers" },
  "ui.Handbook.053": { zh: "子型号", en: "Sub-variants" },
  "ui.Handbook.054": { zh: "市场与世界", en: "Market and the world" },
  "ui.Handbook.055": { zh: "三个标签", en: "Three tabs" },
  "ui.Handbook.056": { zh: "发现虫洞", en: "Finding a wormhole" },
  "ui.Handbook.057": { zh: "怎么扫", en: "How to scan" },
  "ui.Handbook.058": { zh: "发现之后", en: "After a discovery" },
  "ui.Handbook.059": { zh: "三种处置", en: "Three outcomes" },
  "ui.Handbook.060": { zh: "也可以派副船自动探索（约 5 分钟，收益约为亲自探索的四成，参与舰受损但不丢船），或直接放弃。", en: "You can also send an auxiliary ship to explore automatically (about 5 minutes, roughly 40% of the yield of exploring yourself; the ships involved take damage but are never lost), or simply give it up." },
  "ui.Handbook.061": { zh: "回合代价", en: "Turn cost" },
  "ui.Handbook.062": { zh: "全损", en: "Total loss" },
  "ui.Handbook.063": { zh: "产出链", en: "Production chain" },
  "ui.Handbook.064": { zh: "低安安全（安全等级 = 星系风险）", en: "Low-security safety (security rating = system risk)" },
  "ui.Handbook.065": { zh: "安全等级", en: "Security rating" },
  "ui.Handbook.066": { zh: "三档", en: "Three tiers" },
  "ui.Handbook.067": { zh: "什么会遇袭", en: "What can be ambushed" },
  "ui.Handbook.068": { zh: "只打「停留与就地作业」", en: "Only loitering and on-site work are targeted" },
  "ui.Handbook.069": { zh: "低安只对「停留与就地作业」动手：矿带采掘中、打捞作业中、扫描虫洞期间、掩护巡逻驻留都可能撞见巡逻拦截或海盗伏击（星系扫描是无人扫描艇，不在其列）。", en: "Low security only strikes at loitering and on-site work: mining a belt, salvaging, scanning a wormhole or sitting on escort patrol can all run into a patrol interception or a pirate ambush (system scanning uses an unmanned ship and is not on that list)." },
  "ui.Handbook.070": { zh: "AI 副船同样适用。", en: "The same applies to AI auxiliary ships." },
  "ui.Handbook.071": { zh: "入场缓冲", en: "Entry buffer" },
  "ui.Handbook.072": { zh: "与随机事件共用时机", en: "Shares its timing with random events" },
  "ui.Handbook.073": { zh: "在线时", en: "While online" },
  "ui.Handbook.074": { zh: "击退", en: "Repelled" },
  "ui.Handbook.075": { zh: "击退：缴获少量信用点。", en: "Repelled: you take a small amount of credits as prizes." },
  "ui.Handbook.076": { zh: "受损", en: "Damage" },
  "ui.Handbook.077": { zh: "先自动修补", en: "Auto-repair first" },
  "ui.Handbook.078": { zh: "修不动就撤", en: "If repairs cannot keep up, withdraw" },
  "ui.Handbook.079": { zh: "低安遭遇点「⚔ 迎战」时，本场结构损失过半即自动脱离（轻损退出，不给缴获也不额外扣损），随后同样按上面的撤退规则返港——不会把船打到弃船。", en: "Fighting an ⚔ Engage encounter in low security, the ship disengages on its own once structure damage passes half (a light-damage exit: no prizes for the enemy and no extra damage), then flies home by the same retreat rules — it will never be fought to the point of losing the ship." },
  "ui.Handbook.080": { zh: "怎么转", en: "How to switch" },
  "ui.Handbook.081": { zh: "均需两次确认。", en: "Both need a second confirmation." },
  "ui.Handbook.082": { zh: "何时自动暂停", en: "When it pauses automatically" },
  "ui.Handbook.083": { zh: "战斗撤退", en: "Withdrawing from combat" },
  "ui.Handbook.084": { zh: "怎么撤", en: "How to withdraw" },
  "ui.Handbook.085": { zh: "交火中可「⚑ 撤退」（活动栏或战场内，两次确认）：轻损脱离、无弃船风险、立刻回港并停止讨伐（自动撤退与超时判负仍需航程返港）。", en: "You can ⚑ Retreat during a fight (from the activity bar or inside the battle, confirmed twice): you disengage with light damage, with no risk of losing the ship, and dock at once with the hunt called off (automatic retreats and time-limit losses still fly home)." },
  "ui.Handbook.086": { zh: "同型多艘", en: "Several ships of one hull" },
  "ui.Handbook.087": { zh: "卸货", en: "Unloading" },
  "ui.Handbook.088": { zh: "任何舰船到港即自动卸货入仓库；货仓页可手动卸货——空闲停靠的非驾驶船同样可卸。", en: "Any ship unloads into storage automatically on arrival, and the cargo hold page can unload by hand — an idle docked ship that you are not flying can unload too." },
  "ui.Handbook.089": { zh: "不占主控", en: "Uses no manual slot" },
  "ui.Handbook.090": { zh: "8 小时", en: "8 hours" },
  "ui.Handbook.091": { zh: "战斗 · 伤害克制速查", en: "Combat · damage counter quick reference" },
  "ui.Handbook.092": { zh: "承受顺序", en: "Order of absorption" },
  "ui.Handbook.093": { zh: "伤害克制矩阵", en: "Damage counter matrix" },
  "ui.Handbook.094": { zh: "减伤公式", en: "Damage reduction formula" },
  "ui.Handbook.095": { zh: "占主控", en: "Uses the manual slot" },
  "ui.Handbook.096": { zh: "临时离开", en: "Temporarily leaving" },
  "ui.Handbook.097": { zh: "关掉虫洞界面＝临时离开——主控立刻释放、洞内进度原样保存并冻结，回来时要求主控空闲。", en: "Closing the wormhole screen counts as temporarily leaving: the ship is freed at once and progress inside is saved and frozen exactly as it was; coming back requires the ship to be idle." },
  "ui.Handbook.098": { zh: "回合与全损", en: "Turns and total loss" },
  "ui.Handbook.099": { zh: "回合开销", en: "Turn overhead" },
  "ui.Handbook.100": { zh: "临时空间", en: "Temporary space" },
  "ui.Handbook.101": { zh: "占格", en: "Slots used" },
  "ui.Handbook.102": { zh: "寻找人类", en: "Search for humanity" },
  "ui.Handbook.103": { zh: "你的身份", en: "Your identity" },
  "ui.Handbook.104": { zh: "人类已全体失踪——你是一艘前人类时代的舰船 AI。", en: "Humanity has vanished entirely — you are the ship AI of a pre-human era." },
  "ui.Handbook.105": { zh: "以这座章鱼宇宙人统治的母港为起点，往未知的前方继续航行，壮大自身规模，应对各种危险，或许终会有所发现。", en: "From this home port ruled by octopoid aliens, keep flying into the unknown, grow your scale, face whatever comes, and you may find something yet." },
  "ui.Handbook.106": { zh: "{p1} · 加成 {p2}%", en: "{p1} · bonus {p2}%" },
  "ui.Handbook.107": { zh: "仅可制造（市场无成品现货：舰船蓝图船厂定制；已拥有的可二手出售）", en: "Build only (no finished stock on the market: ship blueprints are yard-built; anything you already own can be resold)" },
  "ui.Handbook.108": { zh: "市场流通", en: "Market circulation" },
  "ui.Handbook.109": { zh: "{p1}（弹药）", en: "{p1} (ammo)" },
  "ui.Handbook.110": { zh: "产物介绍", en: "Product overview" },
  "ui.Handbook.111": { zh: "{p1}（装备）", en: "{p1} (modules)" },
  "ui.Handbook.112": { zh: "{p1}（舰船）", en: "{p1} (ships)" },
  "ui.Handbook.113": { zh: "{p1}（数值越大整条线练得越慢）", en: "{p1} (a higher value makes the whole line slower to train)" },
  "ui.Handbook.114": { zh: "小贴士", en: "Tips" },
  "ui.Handbook.115": { zh: "{p1} · 难度 {p2}", en: "{p1} · difficulty {p2}" },
  "ui.Handbook.116": { zh: "其它", en: "Other" },
  "ui.Handbook.117": { zh: "m³/单位", en: "m³/unit" },
  "ui.Handbook.118": { zh: "仅可制造", en: "Build only" },
  "ui.Handbook.119": { zh: "{p1} 分 · 免费", en: "{p1} min · free" },
  "ui.Handbook.120": { zh: "分 · 免费", en: "min · free" },
