  "ui.Industry.038": { zh: "制造中", en: "Manufacturing" },
  "ui.Industry.039": { zh: "已学会", en: "Learned" },
  "ui.Industry.040": { zh: "一次性图纸：不能学习，只能到组装机直接制造一次（开工时消耗这张图纸）", en: "One-use blueprint: cannot be learned; take it to the assembler to build once (the blueprint is consumed when the job starts)" },
  "ui.Industry.041": { zh: "一次性图纸 ×", en: "One-use blueprints ×" },
