  "ui.Industry.045": { zh: "（技能修正后；AI 核心另按效率拉长）", en: " (after skill modifiers; AI-core operation stretches it further by efficiency)" },
  "ui.Industry.046": { zh: "（原 ×", en: " (raw ×" },
