  "ui.Industry.117": { zh: "蓝图书架已有这本图纸 ×{bookCount}：点此学习（不消耗书），学会后本卡永久可造", en: "The Blueprint Shelf already holds ×{bookCount} of this blueprint: click to learn it (the book is not consumed) and this card can then build it for good" },
  "ui.Industry.118": { zh: "虫洞尚未解锁：需「深空工业协会」声望 {WORMHOLE_SCAN_UNLOCK_STANDING}（当前 {whStanding}）——先去协会攒声望", en: "Wormholes are not unlocked yet: needs Deep Space Industry Association reputation {WORMHOLE_SCAN_UNLOCK_STANDING} (currently {whStanding}) — build reputation with the Association first" },
  "ui.Industry.119": { zh: "（货舱 {p1} m³ · {p2} 秒 × {p3} 单位/循环）", en: "(hold {p1} m³ · {p2} s × {p3} units/cycle)" },
