  "ui.Industry.137": { zh: "· 剩余约 {p1}", en: " · about {p1} left" },
  "ui.Industry.138": { zh: "到下方组装机点「市场求购蓝图书」→ 跳到市场的该蓝图行情详情，在那里自己下买单；书到架后回到这里点「学习」即可永久学会配方（重复书只能出售）。一次性图纸用掉即无。", en: "At the assembly unit below, click “Buy the blueprint on the market” → jump to that blueprint's market page and place a buy order yourself; once the book reaches the shelf, come back and click “Learn” to master the recipe for good (a duplicate book can only be sold). A single-use blueprint is gone once used." },
  "ui.Industry.139": { zh: "跳到造船厂并定位这张图纸的卡片（那里才能开工建造）", en: "Jump to the shipyard and locate this blueprint's card (only there can construction start)" },
  "ui.Industry.140": { zh: "跳到组装机并定位这张图纸的卡片（那里才能开工制造）", en: "Jump to the assembly unit and locate this blueprint's card (only there can manufacturing start)" },
  "ui.Industry.141": { zh: "去造船厂", en: "Go to the shipyard" },
  "ui.Industry.142": { zh: "去组装机", en: "Go to the assembly unit" },
  "ui.Industry.143": { zh: "已取消该条制造线：材料全额退回物品仓库（AI 核心已归还）；一次性图纸连同制造名额一起退回蓝图书架。其余线不受影响。", en: "That production line was cancelled: all materials went back to the item warehouse (the AI core has been returned); a single-use blueprint goes back to the blueprint shelf together with its build slot. Other lines are unaffected." },
  "ui.Industry.144": { zh: "基础零件：无需图纸学习，组装机直接可造。", en: "Basic parts: no blueprint needed — the assembly unit can build them directly." },
  "ui.Industry.145": { zh: "无需图纸", en: "No blueprint" },
  "ui.Industry.146": { zh: "已学会", en: "Learned" },
  "ui.Industry.147": { zh: "取消这条制造线：材料按材料学折扣后的实际用量全额退回（AI 核心自动归还）；一次性图纸连同制造名额一起退回蓝图书架。其它线不受影响", en: "Cancel this production line: materials are refunded in full at the actual amounts used after the materials-science discount (AI cores are returned automatically); a single-use blueprint goes back to the blueprint shelf together with its build slot. Other lines are unaffected" },
  "ui.Industry.149": { zh: "舰船蓝图已迁入造船厂子页（panels/Shipyard.tsx），本面板不再渲染舰船。", en: "Ship blueprints have moved to the shipyard subpage (panels/Shipyard.tsx); this panel no longer renders ships." },
  "ui.Industry.150": { zh: "已学会的配方才能开工（基础零件无需图纸）；你亲自开限 1 条、其余每条由一枚 AI 核心驱动（同一蓝图可多条、不同蓝图并行）。", en: "Only learned recipes can be started (basic parts need no blueprint); you can run 1 line by hand, and every other line is driven by one AI core (several lines of the same blueprint are fine, and different blueprints run in parallel)." },
  "ui.Industry.151": { zh: "制造线 {p1} 条 · 装备 {p2} · 零件 {p3} · 消耗品 {p4} · 已学会 {p5}", en: "{p1} production lines · equipment {p2} · parts {p3} · consumables {p4} · learned {p5}" },
  "ui.Industry.152": { zh: "{prodName} ×{units} 件", en: "{prodName} ×{units} pcs" },
