  "ui.IndustryPage.069": { zh: "货柜拆解开工：{p1}（可拆 {total} 件）{who}；每件 {p4} 秒、拆完自动停。", en: "Container breakdown started: {p1} ({total} pieces to open) {who}; {p4} s each, stopping when done." },
  "ui.IndustryPage.070": { zh: "残骸回收开工：{p1}。本炉预占 {p2} m³（1 件 = {RARE_WRECK_VOLUME_M3} m³）转入炉内料账——货仓/仓库不再显示这批料，停炉时未用完部分退回物品仓库。{who}；每批拆 {RECYCLE_BATCH_M3} m³、料尽自动停。", en: "Wreck salvaging started: {p1}. This unit reserved {p2} m³ (1 piece = {RARE_WRECK_VOLUME_M3} m³) into its ledger — the hold and storage no longer show that stock, and whatever is left returns to the warehouse when you stop. {who}; each batch breaks {RECYCLE_BATCH_M3} m³ and the unit stops when the stock is gone." },
  "ui.IndustryPage.071": { zh: "残骸回收开工：{p1}（可拆 {p2} m³，货仓+仓库合计）{who}；每批到点实时扣料、耗尽自动停。", en: "Wreck salvaging started: {p1} ({p2} m³ to break down, hold and storage combined) {who}; each batch draws feedstock as it runs and the unit stops when it is gone." },
  "ui.IndustryPage.072": { zh: "精炼炉开工：{p1}（可炼 ×{p2}，货仓+仓库合计）{who}；每批到点实时扣料、耗尽自动停。", en: "Refinery started: {p1} (×{p2} refinable, hold and storage combined) {who}; each batch draws feedstock as it runs and the unit stops when it is gone." },
  "ui.IndustryPage.073": { zh: "已停该台炉：已完成批保留；本炉未用完的预占料已退回物品仓库（可继续加开其它单位）。", en: "Unit stopped: finished batches are kept and unused reserved feedstock returned to the warehouse (you can start other units)." },
  "ui.IndustryPage.074": { zh: "已停该台炉：原料未锁定无需退回，余料仍留在货仓/仓库原位（可继续加开其它单位）。", en: "Unit stopped: the feedstock was not locked in, so nothing needs returning and the leftovers stay in the hold or storage (you can start other units)." },
  "ui.IndustryPage.075": { zh: "运转 {p1} 台 · 合计余 ×{p2} 件", en: "{p1} units running · ×{p2} pieces left in total" },
