  "ui.IndustryPage.078": { zh: "运转 {p1} 台 · 合计余 ×{p2}（{p3}）", en: "{p1} units running · ×{p2} left in total ({p3})" },
  "ui.IndustryPage.079": { zh: "可用 ×{p1} 件 · 每件 {boxSeconds} 秒 · 拆完自动停（一箱开一件）", en: "×{p1} pieces available · {boxSeconds} s each · stops when done (one container per opening)" },
  "ui.IndustryPage.080": { zh: "可用 {qty} m³（{p2} 件）· 每炉锁 {RARE_WRECK_VOLUME_M3} m³ = 1 件 · 每批 {RECYCLE_BATCH_M3} m³ / {p5} 秒 · 一次起炉 = 开一箱（想多开就再起一炉，同型可多台并行）", en: "{qty} m³ available ({p2} pieces) · each unit locks {RARE_WRECK_VOLUME_M3} m³ = 1 piece · {RECYCLE_BATCH_M3} m³ per batch / {p5} s · one start opens one container (start another unit for more, and several of the same type run in parallel)" },
  "ui.IndustryPage.081": { zh: "可用 {qty} m³ · 每批 {RECYCLE_BATCH_M3} m³ / {p3} 秒 · 约 {p4} 批开完", en: "{qty} m³ available · {RECYCLE_BATCH_M3} m³ per batch / {p3} s · about {p4} batches to finish" },
  "ui.IndustryPage.082": { zh: "可用 ×{p1}（{p2}）· 每批 {batch} 单位 / {cycleS} 秒 · 约 {p5} 批炼完", en: "×{p1} available ({p2}) · {batch} units per batch / {cycleS} s · about {p5} batches to refine" },
  "ui.IndustryPage.083": { zh: "每批产出池内全部原材料（每批 {RECYCLE_BATCH_M3} m³，含残骸提纯学 +8%/级）：各原材料分到的价值 = 每批保底价值 × 价值占比，", en: "Every batch yields every material in the pool ({RECYCLE_BATCH_M3} m³ per batch, including Wreck Refining +8% per level): each material's share of the value = the batch's guaranteed value × its value weight," },
