  "ui.IndustryPage.093": { zh: "每批从本炉预占的料账扣 {p1} m³（货仓/仓库不再显示这批料）", en: "each batch draws {p1} m³ from this unit's reserved ledger (the hold and storage no longer show that stock)" },
  "ui.IndustryPage.094": { zh: "由你亲自再开一台（主控限 1 台）：与现有单位同炉并行，{p1}", en: "Open another unit by hand (the manual slot is limited to one): it runs alongside the existing unit, {p1}" },
  "ui.IndustryPage.095": { zh: "由你亲自运转一台：循环拆解货柜，一箱开一件、每件 {p1} 秒（期间不可离港作业）", en: "Run a unit by hand: continuous container breakdown, one container per item at {p1} s each (you cannot undock for other work meanwhile)" },
  "ui.IndustryPage.096": { zh: "由你亲自运转一台：起炉即预占 1 件（{RARE_WRECK_VOLUME_M3} m³）进本炉料账，每批拆 {RECYCLE_BATCH_M3} m³、料尽自动停（期间不可离港作业）", en: "Run a unit by hand: starting it reserves 1 piece ({RARE_WRECK_VOLUME_M3} m³) into the unit ledger, each batch breaks {RECYCLE_BATCH_M3} m³ and it stops when the stock is gone (you cannot undock for other work meanwhile)" },
  "ui.IndustryPage.097": { zh: "「{p1}」没有精炼产出与市场渠道——先采集可炼原料再来看。", en: "“{p1}” has no refining output and no market channel — gather refinable feedstock and come back." },
  "ui.IndustryPage.098": { zh: "你亲自运转限 1 台，其余每枚 AI 核心各驱动一台；原料不锁定，每批到点从「货仓 + 仓库」实时扣取、耗尽自动停炉。稀有残骸例外：起炉即把整件（1 件 = {RARE_WRECK_VOLUME_M3} m³）转入本炉料账——货仓/仓库不再显示这批料，卡面按\"炉内料账 + 货仓/仓库\"合计数给出，停炉时未用完部分退回物品仓库。精炼：循环运转到料尽自动停炉。残骸回收：保底原材料 + 概率特色掉落。货柜拆解：一箱开一件，每件 90 秒。", en: "You can run one unit by hand and each AI core drives one more; feedstock is not locked in, so every batch draws from the hold and storage as it runs and the unit stops when the stock is gone. Rare wrecks are the exception: starting the unit moves the whole piece (1 piece = {RARE_WRECK_VOLUME_M3} m³) into this unit's ledger — the hold and storage no longer show that stock, the card total combines the unit ledger with the hold and storage, and whatever is left returns to the warehouse when you stop. Refining loops until the stock runs out; wreck salvaging pays guaranteed materials plus a chance at signature loot; container breakdown opens one container per item at 90 seconds each." },
  "ui.IndustryPage.099": { zh: " · 货柜 {p1}", en: " · containers {p1}" },
  "ui.IndustryPage.100": { zh: " · 当前 {shownCount} 张", en: " · {shownCount} cards now" },
  "ui.IndustryPage.101": { zh: "前往星图「矿带开采」定位出产该原料的矿带{p1}", en: "Find the belt that yields this material on the star map under Belt mining{p1}" },
  "ui.IndustryPage.102": { zh: "% · 运转 {n} ", en: "% · {n} running " },
  "ui.IndustryPage.103": { zh: " · 残骸 {n}", en: " · wrecks {n}" },
  "ui.IndustryPage.104": { zh: "停", en: "Stop" },
  "ui.IndustryPage.105": { zh: "停炉失败。", en: "Stopping the unit failed." },
  "ui.IndustryPage.106": { zh: "净收益估算：每批产物（原材料站内收价） − 每批耗料价值（原料站内收价），× 每小时批次数；不随市场、未计成交税。毛产值 ≈{p1} 信用点/h；{p2}", en: "Net income estimate: each batch of product (station buy price for materials) − the value of the feedstock each batch consumes (station buy price), × batches per hour; it does not follow the market and excludes trade tax. Gross output ≈{p1} credits/h; {p2}" },
  "ui.IndustryPage.107": { zh: "当前批进度 {p1}%（{p2}；{p3}）", en: "Current batch progress {p1}% ({p2}; {p3})" },
  "ui.IndustryPage.108": { zh: " · 匹配 {n} 张", en: " · {n} cards match" },
  "ui.IndustryPage.109": { zh: "没有匹配的货柜——换个关键词试试（支持名称与说明）。", en: "No containers match — try another keyword (name and description both work)." },
  /* 2026-09-21 船长报障「各个子标签页和筛选似乎并没有本地化」：工业页「造船厂」子标签与造船厂面板标题原先写死中文，补 id */
  "ui.IndustryPage.110": { zh: "造船厂", en: "Shipyard" },
  "ui.IndustryPage.114": { zh: "造船厂", en: "Shipyard" },
  "ui.IndustryPage.115": { zh: "舰船蓝图在这里开工：已学会的配方才能建造（一次性图纸有书即用）；你亲自开限 1 条、其余每条由一枚 AI 核心驱动。造好的船先进舰船仓库。蓝图书仍到「蓝图书架」学习。", en: "Ship blueprints start here: only learned recipes can be built (one-use blueprints build straight from the book). You run one line by hand and each AI core drives one more. Finished ships go into ship storage first. Blueprint books are still studied at the Blueprint Shelf." },
  "ui.IndustryPage.111": { zh: "搜索资源、残骸或产出物…", en: "Search resources, wrecks or output…" },
  "ui.IndustryPage.112": { zh: "启动失败。", en: "Could not start." },
  "ui.IndustryPage.113": { zh: "单位数 = 该价值 ÷ 单价——单价高的原材料每批不足 1 单位会累计到够 1 再入库；每批总价值有 ±10% 抖动，以回收拆解结算为准。", en: "Unit count = that value ÷ unit price — for pricey feedstock, batches that come to less than 1 unit accumulate until a whole unit can be stored; each batch's total value wobbles by ±10%, and the recycling settlement is what counts." },
