  "ui.ItemsPage.034": { zh: "装备库是空的——购买 / 制造后先存放于此，再到「装配」页安装。", en: "Module Storage is empty — bought or built modules land here first, then you fit them on the Fitting page." },
  "ui.ItemsPage.035": { zh: "装到当前驾驶船的货仓（按单位体积占舱）", en: "Load into the piloted ship's hold (takes up its unit volume)" },
  "ui.ItemsPage.036": { zh: "装入船货仓携带（按 1 m³/件 计入货舱）；安装到槽位请到「装配」页（装配台取料自装备库，船上装备需先卸回）", en: "Load into the ship's hold to carry it (1 m³ per unit counts against the hold); to fit it into a slot go to the Fitting page (the fitting bay draws from Module Storage, so modules already aboard have to be unloaded first)" },
