  "ui.MapPage.015": { zh: "——本卡「停止开采」也可直接操作；想换船去「舰船」页切换驾驶，旧船会自动返航卸货。", en: "— the Stop Mining button on this card works too; to change ships, switch pilots on the Ships page and the old ship flies home to unload by itself." },
  "ui.MapPage.016": { zh: "在下方矿带卡片上开始采掘——指令下达即抵达矿带开工。", en: "Start mining from a belt card below — the order puts the ship to work on the belt at once." },
  "ui.MapPage.017": { zh: "自动循环（满舱返航卸入仓库 → 去程并入返航 → 自动再采掘）", en: "Auto loop (a full hold flies home to unload, the outbound leg merges into the return, then mining resumes)" },
