  "ui.MapPage.074": { zh: "主控打捞作业进行中——AI 不受限，仍可派副船（副船独立于主控）", en: "Manual salvage is running — AI work is not restricted and auxiliary ships can still be sent (they are independent of the manual slot)" },
  "ui.MapPage.075": { zh: "指派 AI 副船打捞此星系（自动循环，取消任务才结束）", en: "Send an AI auxiliary ship to salvage this system (it loops until the task is cancelled)" },
