  "ui.MarketPage.022": { zh: "指派 AI 副船任务时使用，任务结束自动归还核心库；更高阶核心通常由高威胁远征缴获或奇货市场流出。", en: "Used when assigning AI auxiliary tasks, and returned to the core library when the task ends; higher-tier cores usually come from high-threat expeditions or leak out through the Enigma market." },
  "ui.MarketPage.023": { zh: "自己的库存：物品 → 物品仓库、装备 → 装备库、蓝图 → 图书存量、AI 核心 → 核心库、舰船 → 舰船仓库 ＋ 在役舰队同型艘数（挂单托管中的不计）；舰船出售在舰船页「舰船仓库」操作", en: "Your own stock: items to the warehouse, modules to Module Storage, blueprints to book stock, AI cores to the core library, ships to Ship Storage plus same-hull counts in the active fleet (escrowed listings excluded); ships are sold from Ship Storage on the Ships page" },
  "ui.MarketPage.024": { zh: "已掌握该蓝图：可在工业页无限自制", en: "Blueprint learned: unlimited manufacturing on the Industry page" },
  "ui.MarketPage.025": { zh: "已学习", en: "Learned" },
